describe('Payment Processing Loading State', () => {
  beforeEach(() => {
    cy.visit('/payment');
    cy.intercept('POST', '/api/payment/process', {
      delay: 2000,
      statusCode: 200,
      body: { success: true, transactionId: 'TXN123456' }
    }).as('processPayment');
  });

  it('should display loading state while payment is processing', () => {
    cy.get('[data-testid="card-number"]').type('4111111111111111');
    cy.get('[data-testid="expiry-date"]').type('12/25');
    cy.get('[data-testid="cvv"]').type('123');
    cy.get('[data-testid="cardholder-name"]').type('John Doe');

    cy.get('[data-testid="submit-payment-btn"]').click();

    cy.get('[data-testid="loading-spinner"]').should('be.visible');
    cy.get('[data-testid="loading-text"]').should('contain', 'Processing your payment');
    cy.get('[data-testid="submit-payment-btn"]').should('be.disabled');

    cy.wait('@processPayment');

    cy.get('[data-testid="loading-spinner"]').should('not.exist');
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Payment successful');
  });

  it('should handle loading state timeout and display error message', () => {
    cy.intercept('POST', '/api/payment/process', {
      delay: 35000,
      statusCode: 408,
      body: { error: 'Request timeout' }
    }).as('processPaymentTimeout');

    cy.get('[data-testid="card-number"]').type('4111111111111111');
    cy.get('[data-testid="expiry-date"]').type('12/25');
    cy.get('[data-testid="cvv"]').type('123');
    cy.get('[data-testid="cardholder-name"]').type('Jane Doe');

    cy.get('[data-testid="submit-payment-btn"]').click();

    cy.get('[data-testid="loading-spinner"]').should('be.visible');
    cy.get('[data-testid="loading-text"]').should('contain', 'Processing your payment');

    cy.get('[data-testid="error-message"]', { timeout: 35000 }).should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Payment processing timed out');
    cy.get('[data-testid="loading-spinner"]').should('not.exist');
    cy.get('[data-testid="submit-payment-btn"]').should('not.be.disabled');
  });

  it('should show loading state with progress indicator for extended processing', () => {
    cy.intercept('POST', '/api/payment/process', {
      delay: 5000,
      statusCode: 200,
      body: { success: true, transactionId: 'TXN789012' }
    }).as('processPaymentExtended');

    cy.get('[data-testid="card-number"]').type('5555555555554444');
    cy.get('[data-testid="expiry-date"]').type('06/26');
    cy.get('[data-testid="cvv"]').type('456');
    cy.get('[data-testid="cardholder-name"]').type('Bob Smith');

    cy.get('[data-testid="submit-payment-btn"]').click();

    cy.get('[data-testid="loading-spinner"]').should('be.visible');
    cy.get('[data-testid="progress-bar"]').should('be.visible');
    cy.get('[data-testid="progress-bar"]').should('have.attr', 'aria-valuenow');

    cy.get('[data-testid="progress-bar"]').invoke('attr', 'aria-valuenow').then((value) => {
      expect(parseInt(value)).to.be.greaterThan(0);
    });

    cy.wait('@processPaymentExtended');

    cy.get('[data-testid="loading-spinner"]').should('not.exist');
    cy.get('[data-testid="progress-bar"]').should('not.exist');
    cy.get('[data-testid="success-message"]').should('be.visible');
  });

  it('should prevent multiple payment submissions during loading state', () => {
    cy.intercept('POST', '/api/payment/process', {
      delay: 3000,
      statusCode: 200,
      body: { success: true, transactionId: 'TXN345678' }
    }).as('processPayment');

    cy.get('[data-testid="card-number"]').type('4111111111111111');
    cy.get('[data-testid="expiry-date"]').type('12/25');
    cy.get('[data-testid="cvv"]').type('123');
    cy.get('[data-testid="cardholder-name"]').type('Alice Johnson');

    cy.get('[data-testid="submit-payment-btn"]').click();

    cy.get('[data-testid="loading-spinner"]').should('be.visible');
    cy.get('[data-testid="submit-payment-btn"]').should('be.disabled');

    cy.get('[data-testid="submit-payment-btn"]').click({ force: true });

    cy.get('@processPayment.all').then((interceptions) => {
      expect(interceptions).to.have.lengthOf(1);
    });

    cy.wait('@processPayment');
    cy.get('[data-testid="success-message"]').should('be.visible');
  });
});
